# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTATİSTİKSEL ARAŞTIRMA SÜRECİ VE VERİ TÜRLERİ (MAT.7.6.1)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Kategorik (Nitel/Sınıflamalı) Veri</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Tanım: Sayısal ölçümden ziyade</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  nitelik, grup veya kategori bildirir.</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Örnekler: En sevilen spor dalı,</text>\n  <text x="44" y="154" font-size="11" fill="#334155">  kan grupları (A, B, AB, 0), göz rengi,</text>\n  <text x="44" y="170" font-size="11" fill="#334155">  okunan eser türü, seçmeli dersler.</text>\n  <text x="183" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Uygun Grafikler: Sütun Grafiği,</text>\n  <text x="183" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Daire Grafiği, Nokta Grafiği</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Nicel (Sayısal: Kesikli ve Sürekli) Veri</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Kesikli (Sayma ile): Kardeş sayısı,</text>\n  <text x="378" y="114" font-size="11" fill="#334155">  çözülen soru adedi, gol sayısı.</text>\n  <text x="378" y="138" font-size="11" fill="#334155">• Sürekli (Ölçme ile - Ondalıklı olabilir):</text>\n  <text x="378" y="154" font-size="11" fill="#334155">  Boy uzunluğu (1,64 m), kütle (52,5 kg),</text>\n  <text x="378" y="170" font-size="11" fill="#334155">  hava sıcaklığı, koşu süresi (saniye).</text>\n  <text x="517" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Uygun Grafikler: Çizgi Grafiği (zamanla</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">değişim), Sütun ve Nokta Grafiği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VERİ GÖRSELLEŞTİRME ARAÇLARI: SÜTUN, ÇİZGİ VE DAİRE GRAFİĞİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Sütun Grafiği</text>\n  <rect x="55" y="135" width="28" height="65" fill="#3b82f6"/>\n  <rect x="98" y="105" width="28" height="95" fill="#2563eb"/>\n  <rect x="141" y="150" width="28" height="50" fill="#60a5fa"/>\n  <rect x="184" y="120" width="28" height="80" fill="#1d4ed8"/>\n  <line x1="45" y1="200" x2="220" y2="200" stroke="#334155" stroke-width="1.5"/>\n  <text x="130" y="220" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Kategorilerin büyüklüklerini</text>\n  <text x="130" y="233" text-anchor="middle" font-size="10.5" fill="#1e3a8a">karşılaştırmak için idealdir</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Çizgi Grafiği</text>\n  <polyline points="270,180 310,140 350,155 390,110 430,95" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <circle cx="270" cy="180" r="4" fill="#15803d"/>\n  <circle cx="310" cy="140" r="4" fill="#15803d"/>\n  <circle cx="350" cy="155" r="4" fill="#15803d"/>\n  <circle cx="390" cy="110" r="4" fill="#15803d"/>\n  <circle cx="430" cy="95" r="4" fill="#15803d"/>\n  <line x1="260" y1="200" x2="440" y2="200" stroke="#334155" stroke-width="1.5"/>\n  <text x="350" y="220" text-anchor="middle" font-size="10.5" fill="#166534">Sürekli verinin zamana göre</text>\n  <text x="350" y="233" text-anchor="middle" font-size="10.5" fill="#166534">artış/azalış eğilimini gösterir</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Daire Grafiği (360°)</text>\n  <circle cx="570" cy="140" r="46" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>\n  <path d="M570,140 L570,94 A46,46 0 0,1 616,140 Z" fill="#f97316"/>\n  <path d="M570,140 L616,140 A46,46 0 0,1 570,186 Z" fill="#3b82f6"/>\n  <text x="570" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Merkez Açı = (Veri / Toplam) × 360°</text>\n  <text x="570" y="228" text-anchor="middle" font-size="10.5" fill="#78350f">Parça-bütün oranını gösterir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VERİ ÖZETLEME ÖLÇÜLERİ: ORTALAMA, ORTANCA, TEPE DEĞER VE AÇIKLIK</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Aritmetik Ortalama</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Formül: Verilerin Toplamı /</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  Veri Sayısı (Terim Sayısı)</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• Örnek: 10, 12, 12, 16, 20</text>\n  <text x="40" y="154" font-size="11" fill="#334155">  Toplam = 70 → 70 / 5 = 14</text>\n  <text x="40" y="180" font-size="10.5" font-weight="bold" fill="#1e40af">• Çok uç (aşırı büyük/küçük)</text>\n  <text x="40" y="196" font-size="10.5" font-weight="bold" fill="#1e40af">  değerlerden doğrudan etkilenir</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Ortanca (Medyan)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Veriler küçükten büyüğe</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  sıralandığında tam ORTADAKİ</text>\n  <text x="260" y="130" font-size="11" fill="#334155">  değerdir (çift sayıda ise</text>\n  <text x="260" y="146" font-size="11" fill="#334155">  ortadaki ikisinin ortalaması).</text>\n  <text x="260" y="172" font-size="10.5" font-weight="bold" fill="#166534">• Uç (aykırı) değerler olduğunda</text>\n  <text x="260" y="188" font-size="10.5" font-weight="bold" fill="#166534">  en güvenilir merkez ölçüsüdür</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Tepe Değer (Mod) ve Yayılım</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Tepe Değer (Mod): Veri grubunda</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  EN ÇOK TEKRAR EDEN değerdir.</text>\n  <text x="480" y="138" font-size="11" fill="#334155">• Açıklık: En Büyük − En Küçük</text>\n  <text x="480" y="162" font-size="11" fill="#334155">• Ortalama Mutlak Sapma (OMS):</text>\n  <text x="480" y="178" font-size="10.5" fill="#78350f">  Verilerin ortalamaya olan</text>\n  <text x="480" y="194" font-size="10.5" fill="#78350f">  uzaklıklarının ortalamasıdır</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
